const row = $input.first().json || {};
const body = row.body && typeof row.body === 'object' ? row.body : row;
return [{ json: {
  ...body,
  project_id: body.project_id || '',
  selected_concept_id: body.selected_concept_id || body.concept_id || '',
  concept_context_path: body.concept_context_path || body.context_path || '',
  review_after_generation: true,
} }];

const fs = require('fs');
const path = require('path');

const row = $input.first().json || {};
const PROJECT_ROOT = require('process').env.PROJECT_ROOT || require('path').join(require('os').homedir(), 'Downloads', 'tiktok-n8n-workflow-pack');
const contextDir = require('path').join(PROJECT_ROOT, '.n8n-local-cache', 'concept-context');
const selectedDir = require('path').join(PROJECT_ROOT, '.n8n-local-cache', 'selected-concepts');
const projectDir = require('path').join(PROJECT_ROOT, '.n8n-local-cache', 'project-state');
fs.mkdirSync(selectedDir, { recursive: true });
fs.mkdirSync(projectDir, { recursive: true });

const projectId = String(row.project_id || '').trim();
const selectedConceptId = String(row.selected_concept_id || '').trim();
const contextPath = String(row.concept_context_path || '').trim() || path.join(contextDir, 'concept_context_' + projectId + '.json');

if (!projectId) {
  throw new Error('concept_select_restore：缺少 project_id');
}
if (!selectedConceptId) {
  throw new Error('concept_select_restore：缺少 selected_concept_id');
}
if (!fs.existsSync(contextPath)) {
  throw new Error('concept_select_restore：concept_context 不存在 ' + contextPath);
}

const context = JSON.parse(fs.readFileSync(contextPath, 'utf8'));
const concepts = Array.isArray(context.creative_concepts)
  ? context.creative_concepts
  : JSON.parse(context.creative_concepts_json || '[]');
if (!Array.isArray(concepts) || !concepts.length) {
  throw new Error('concept_select_restore：creative_concepts 为空');
}

const selectedIndex = concepts.findIndex((concept) => String(concept.concept_id || '') === selectedConceptId);
if (selectedIndex < 0) {
  throw new Error('concept_select_restore：selected_concept_id 未匹配到创意方向 ' + selectedConceptId);
}

const selectedConcept = concepts[selectedIndex];
const selectedPayload = {
  project_id: projectId,
  selected_concept_id: selectedConceptId,
  selected_concept_index: selectedIndex,
  selected_concept_json: selectedConcept,
  selected_at: new Date().toISOString(),
};
const selectedPath = path.join(selectedDir, 'selected_concept_' + String(projectId).replace(/[^a-zA-Z0-9_-]+/g, '_') + '.json');
fs.writeFileSync(selectedPath, JSON.stringify(selectedPayload, null, 2));
const projectStatePath = path.join(projectDir, 'project_' + String(projectId).replace(/[^a-zA-Z0-9_-]+/g, '_') + '.json');
fs.writeFileSync(projectStatePath, JSON.stringify({
  project_id: projectId,
  product_name: context.product_name || '',
  target_market: context.target_market || '',
  target_language: context.target_language || '',
  creative_task_type: context.creative_task_type || '',
  selected_concept_id: selectedConceptId,
  status: row.manual_regeneration_requested ? 'storyboard_regenerating' : 'concept_selected',
  updated_at: new Date().toISOString(),
}, null, 2));

return [{ json: {
  ...context,
  project_id: projectId,
  selected_concept_id: selectedConceptId,
  selected_concept_index: selectedIndex,
  selected_concept_name: selectedConcept.concept_name || '',
  selected_concept_json: JSON.stringify(selectedConcept),
  selected_concept: selectedConcept,
  concept_context_path: contextPath,
  selected_concept_record_path: selectedPath,
  status: row.manual_regeneration_requested ? 'storyboard_regenerating' : 'concept_selected'
} }];

const input = $input.item.json || {};

const rawConcepts = input.creative_concepts_json;
if (!rawConcepts) {
  throw new Error('creative_concepts_json 为空，无法提取选中方向');
}

let concepts;
try {
  concepts = JSON.parse(rawConcepts);
} catch (error) {
  throw new Error('creative_concepts_json 不是合法 JSON: ' + error.message);
}

if (!Array.isArray(concepts) || concepts.length === 0) {
  throw new Error('creative_concepts_json 解析后不是有效数组');
}

const selectedIndex = Number(input.selected_concept_index ?? 0);
if (selectedIndex < 0 || selectedIndex >= concepts.length) {
  throw new Error(`selected_concept_index 超出范围，当前值: ${selectedIndex}`);
}

const selectedConcept = concepts[selectedIndex];

return [
  {
    json: {
      ...input,
      project_id: input.project_id || '',
      product_name: input.product_name || '',
      target_market: input.target_market || '',
      target_language: input.target_language || '',
      creative_task_type: input.creative_task_type || '',
      director_status: input.director_status || '',
      product_understanding_json: input.product_understanding_json || '',
      audience_persona_json: input.audience_persona_json || '',
      tiktok_content_strategy_json: input.tiktok_content_strategy_json || '',
      creative_concepts_json: input.creative_concepts_json || '',
      selected_concept_index: selectedIndex,
      selected_concept_name: input.selected_concept_name || selectedConcept.concept_name || '',
      selected_concept_json: JSON.stringify(selectedConcept),
      selected_concept: selectedConcept,
      concept_count: input.concept_count || concepts.length,
      created_at: input.created_at || ''
    }
  }
];

const fs = require('fs');
const item = $input.first();
const binary = item.binary || {};
const row = item.json || {};

function readImageBase64(binaryKey, pathValue) {
  if (pathValue && fs.existsSync(pathValue)) {
    return fs.readFileSync(pathValue).toString('base64');
  }
  try {
    return this.helpers.getBinaryDataBuffer(0, binaryKey).then((buf) => buf.toString('base64'));
  } catch (error) {
    return '';
  }
}

const imagePaths = Array.isArray(row.product_image_local_paths) ? row.product_image_local_paths : [];
const metaImages = Array.isArray(row.product_images_meta) ? row.product_images_meta : [];
const image1Path = row.image_1_path || imagePaths[0] || metaImages[0]?.path || '';
const image2Path = row.image_2_path || imagePaths[1] || metaImages[1]?.path || '';
const imageCount = Number(row.product_image_count ?? row.image_count ?? imagePaths.length ?? metaImages.length ?? 0);

const image1Base64 = imageCount >= 1 ? await readImageBase64.call(this, 'product_images_0', image1Path) : '';
const image2Base64 = imageCount >= 2 ? await readImageBase64.call(this, 'product_images_1', image2Path) : '';
const mime1 = binary.product_images_0?.mimeType || row.image_1_mime || metaImages[0]?.mimeType || 'image/jpeg';
const mime2 = binary.product_images_1?.mimeType || row.image_2_mime || metaImages[1]?.mimeType || 'image/jpeg';

function tpl(str, vars) {
  let out = str;
  for (const [k, v] of Object.entries(vars)) {
    out = out.split('{{' + k + '}}').join(v == null ? '' : String(v));
  }
  return out;
}

const prompts = $('Prompt Library').first().json;
const s = prompts.script;

const userText = tpl(s.user_template, {
  project_id: row.project_id,
  product_name: row.product_name,
  target_market: row.target_market,
  target_language: row.target_language,
  creative_task_type: row.creative_task_type,
  product_understanding_json: row.product_understanding_json || '',
  audience_persona_json: row.audience_persona_json || '',
  tiktok_content_strategy_json: row.tiktok_content_strategy_json || '',
  selected_concept_name: row.selected_concept_name,
  selected_concept_json: row.selected_concept_json || '',
});

const hardConstraintBlock = [
  '',
  '【Form 业务硬约束】',
  '- target_market 必须严格使用：' + (row.target_market || ''),
  '- target_language 必须严格使用：' + (row.target_language || ''),
  '- creative_task_type 必须严格使用：' + (row.creative_task_type || ''),
  '- creative_task_type_rules：' + (row.creative_task_type_rules_json || '{}'),
  '- selected_concept 是人工选择后的硬约束，不允许推翻。',
  '- product_image_count：' + imageCount,
].join('\n');

const parts = [{ text: userText + hardConstraintBlock }];
if (imageCount >= 1 && image1Base64) parts.push({ inline_data: { mime_type: mime1, data: image1Base64 } });
if (imageCount >= 2 && image2Base64) parts.push({ inline_data: { mime_type: mime2, data: image2Base64 } });

return [
  {
    json: {
      ...row,
      image_1_path: image1Path,
      image_2_path: image2Path,
      image_1_base64: image1Base64,
      image_2_base64: image2Base64,
      image_1_mime: mime1,
      image_2_mime: mime2,
      image_count: imageCount,
      product_image_count: imageCount,
      request_body: {
        system_instruction: { parts: [{ text: s.system_instruction }] },
        contents: [{ role: 'user', parts }],
        generationConfig: s.generation_config,
      },
    },
  },
];

const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
function extractFirstJsonValue(text) {
  const raw = String(text || '').trim();
  if (!raw) return '{}';

  const tick = String.fromCharCode(96);
  const fence = tick + tick + tick;
  const fencedJson = new RegExp(fence + 'json\\s*([\\s\\S]*?)\\s*' + fence, 'i');
  const fencedAny = new RegExp(fence + '\\s*([\\s\\S]*?)\\s*' + fence, 'i');
  const fenced = raw.match(fencedJson) || raw.match(fencedAny);
  const source = fenced?.[1] ? fenced[1].trim() : raw;

  for (const start of [source.indexOf('{'), source.indexOf('[')].filter((x) => x >= 0).sort((a, b) => a - b)) {
    const open = source[start];
    const close = open === '{' ? '}' : ']';
    let depth = 0;
    let inString = false;
    let escape = false;
    for (let i = start; i < source.length; i++) {
      const ch = source[i];
      if (inString) {
        if (escape) {
          escape = false;
        } else if (ch === '\\') {
          escape = true;
        } else if (ch === '"') {
          inString = false;
        }
        continue;
      }
      if (ch === '"') {
        inString = true;
      } else if (ch === open) {
        depth++;
      } else if (ch === close) {
        depth--;
        if (depth === 0) return source.slice(start, i + 1).trim();
      }
    }
  }

  return source;
}

let parsed = {};
try {
  parsed = JSON.parse(extractFirstJsonValue(raw));
} catch (error) {
  throw new Error('脚本框架生成返回无法提取合法 JSON: ' + error.message + '，原始返回前800字=' + String(raw).slice(0, 800));
}

// 尽量从上游节点取基础信息
const source =
  $('Code in JavaScript').first()?.json ||
  $('Edit Fields3').first()?.json ||
  $('脚本请求体组装').first()?.json ||
  {};

return [
  {
    json: {
      project_id: source.project_id || '',
      product_name: source.product_name || '',
      target_market: source.target_market || '',
      target_language: source.target_language || '',
      creative_task_type: source.creative_task_type || '',

      selected_concept_name_original: parsed.script_overview?.selected_concept_name_original || '',
      script_concept_label: parsed.script_overview?.script_concept_label || '',
      script_goal: parsed.script_overview?.script_goal || '',
      visual_style: parsed.script_overview?.visual_style || '',
      identified_product_type: parsed.script_overview?.identified_product_type || '',
      product_presentation_logic: parsed.script_overview?.product_presentation_logic || '',
      core_visual_focus: parsed.script_overview?.core_visual_focus || '',
      total_shots: parsed.script_overview?.total_shots || 0,
      hook_strategy: parsed.script_overview?.hook_strategy || '',

      full_script_json: JSON.stringify(parsed),
      created_at: new Date().toISOString(),

      shots: parsed.shots || [],
      selected_concept_id: source.selected_concept_id || '',
      concept_context_path: source.concept_context_path || ''
    }
  }
];

const shots = $json.shots || [];

return shots.map((shot, index) => {
  return {
    json: {
      project_id: $json.project_id || '',
      selected_concept_name_original: $json.selected_concept_name_original || '',
      script_concept_label: $json.script_concept_label || '',

      shot_id: shot.shot_id || '',
      shot_order: index + 1,
      stage: shot.stage || '',
      duration: shot.duration || '',
      scene_setting: shot.scene_setting || '',
      visual_action: shot.visual_action || '',
      product_state: shot.product_state || '',
      camera_movement: shot.camera_movement || '',
      expression_focus: shot.expression_focus || '',
      optional_voiceover_local: shot.optional_voiceover_local || '',
      continuity_requirements: shot.continuity_requirements || '',

      created_at: new Date().toISOString()
    }
  };
});

const fs = require('fs');
const item = $input.first();
const json = item.json || {};
const binary = item.binary || {};

let image1Base64 = json.image_1_base64 || '';
let image2Base64 = json.image_2_base64 || '';

const imagePaths = Array.isArray(json.product_image_local_paths) ? json.product_image_local_paths : [];
const metaImages = Array.isArray(json.product_images_meta) ? json.product_images_meta : [];
const image1Path = json.image_1_path || imagePaths[0] || metaImages[0]?.path || '';
const image2Path = json.image_2_path || imagePaths[1] || metaImages[1]?.path || '';
const imageCount = Number(json.product_image_count ?? json.image_count ?? imagePaths.length ?? metaImages.length ?? 0);

if (!image1Base64 && imageCount >= 1 && image1Path && fs.existsSync(image1Path)) {
  image1Base64 = fs.readFileSync(image1Path).toString('base64');
}
if (!image2Base64 && imageCount >= 2 && image2Path && fs.existsSync(image2Path)) {
  image2Base64 = fs.readFileSync(image2Path).toString('base64');
}
try {
  if (!image1Base64 && imageCount >= 1) {
    const img1 = await this.helpers.getBinaryDataBuffer(0, 'product_images_0');
    image1Base64 = img1.toString('base64');
  }
} catch (e) {}
try {
  if (!image2Base64 && imageCount >= 2) {
    const img2 = await this.helpers.getBinaryDataBuffer(0, 'product_images_1');
    image2Base64 = img2.toString('base64');
  }
} catch (e) {}

const mime1 = binary.product_images_0?.mimeType || json.image_1_mime || metaImages[0]?.mimeType || 'image/jpeg';
const mime2 = binary.product_images_1?.mimeType || json.image_2_mime || metaImages[1]?.mimeType || 'image/jpeg';

const shots = json.shots || [];
const expectedTotalPanels = shots.length;
const expectedLayoutLabel = '6-panel (3x2, target 27:32)';

if (expectedTotalPanels !== 6) {
  throw new Error('分镜提示词生成前校验失败：当前工作流已强制六宫格，shots 数量必须为 6，实际为 ' + expectedTotalPanels);
}

let fullScriptJson = {
  script_overview: {
    selected_concept_name_original: json.selected_concept_name_original || '',
    script_concept_label: json.script_concept_label || '',
    script_goal: json.script_goal || '',
    visual_style: json.visual_style || '',
    identified_product_type: json.identified_product_type || '',
    product_presentation_logic: json.product_presentation_logic || '',
    core_visual_focus: json.core_visual_focus || '',
    total_shots: json.total_shots || 6,
    hook_strategy: json.hook_strategy || '',
  },
  shots,
};

if (json.full_script_json) {
  try { fullScriptJson = JSON.parse(json.full_script_json); } catch (e) {}
}

function tpl(str, vars) {
  let out = str;
  for (const [k, v] of Object.entries(vars)) {
    out = out.split('{{' + k + '}}').join(v == null ? '' : String(v));
  }
  return out;
}

const prompts = $('Prompt Library').first().json;
const sb = prompts.storyboard;

const userText = tpl(sb.user_template, {
  project_id: json.project_id || '',
  product_name: json.product_name || '',
  target_market: json.target_market || '',
  target_language: json.target_language || '',
  creative_task_type: json.creative_task_type || '',
  selected_concept_name_original: json.selected_concept_name_original || '',
  script_concept_label: json.script_concept_label || '',
  script_goal: json.script_goal || '',
  visual_style: json.visual_style || '',
  identified_product_type: json.identified_product_type || '',
  product_presentation_logic: json.product_presentation_logic || '',
  core_visual_focus: json.core_visual_focus || '',
  hook_strategy: json.hook_strategy || '',
  expected_total_panels: String(expectedTotalPanels),
  expected_layout_label: expectedLayoutLabel,
  full_script_json: JSON.stringify(fullScriptJson, null, 2),
  shots_json: JSON.stringify(shots, null, 2),
});

const hardConstraintBlock = [
  '',
  '【Form 业务硬约束】',
  '- target_market 必须严格使用：' + (json.target_market || ''),
  '- target_language 必须严格使用：' + (json.target_language || ''),
  '- creative_task_type 必须严格使用：' + (json.creative_task_type || ''),
  '- creative_task_type_rules：' + (json.creative_task_type_rules_json || '{}'),
  '- recommended_grid：' + (json.recommended_grid || '6_grid'),
  '- selected_concept 是人工选择后的硬约束，不允许推翻。',
  '- product_image_count：' + imageCount,
].join('\n');

const parts = [{ text: userText + hardConstraintBlock }];
if (imageCount >= 1 && image1Base64) parts.push({ inline_data: { mime_type: mime1, data: image1Base64 } });
if (imageCount >= 2 && image2Base64) parts.push({ inline_data: { mime_type: mime2, data: image2Base64 } });

return [
  {
    json: {
      ...json,
      image_1_path: image1Path,
      image_2_path: image2Path,
      image_1_base64: image1Base64,
      image_2_base64: image2Base64,
      image_1_mime: mime1,
      image_2_mime: mime2,
      image_count: imageCount,
      product_image_count: imageCount,
      request_body: {
        system_instruction: { parts: [{ text: sb.system_instruction }] },
        contents: [{ role: 'user', parts }],
        generationConfig: sb.generation_config,
      },
    },
  },
];

const item = $input.first();
const rawText = item.json?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
function extractFirstJsonValue(text) {
  const raw = String(text || '').trim();
  if (!raw) return '{}';

  const tick = String.fromCharCode(96);
  const fence = tick + tick + tick;
  const fencedJson = new RegExp(fence + 'json\\s*([\\s\\S]*?)\\s*' + fence, 'i');
  const fencedAny = new RegExp(fence + '\\s*([\\s\\S]*?)\\s*' + fence, 'i');
  const fenced = raw.match(fencedJson) || raw.match(fencedAny);
  const source = fenced?.[1] ? fenced[1].trim() : raw;

  for (const start of [source.indexOf('{'), source.indexOf('[')].filter((x) => x >= 0).sort((a, b) => a - b)) {
    const open = source[start];
    const close = open === '{' ? '}' : ']';
    let depth = 0;
    let inString = false;
    let escape = false;
    for (let i = start; i < source.length; i++) {
      const ch = source[i];
      if (inString) {
        if (escape) {
          escape = false;
        } else if (ch === '\\') {
          escape = true;
        } else if (ch === '"') {
          inString = false;
        }
        continue;
      }
      if (ch === '"') {
        inString = true;
      } else if (ch === open) {
        depth++;
      } else if (ch === close) {
        depth--;
        if (depth === 0) return source.slice(start, i + 1).trim();
      }
    }
  }

  return source;
}

let parsed = {};
try {
  parsed = JSON.parse(extractFirstJsonValue(rawText));
} catch (e) {
  throw new Error('分镜提示词生成返回无法提取合法 JSON: ' + e.message + '，原始返回前800字=' + String(rawText).slice(0, 800));
}

const scriptRow = $('提取脚本框架JSON').first()?.json || {};
const shots = Array.isArray(scriptRow.shots) ? scriptRow.shots : [];
const expectedTotalPanels = shots.length;
const actualTotalPanels = Number(parsed?.storyboard_overview?.total_panels ?? 0);

if (expectedTotalPanels !== 6) {
  throw new Error('前置 shots 数量异常：当前工作流已强制六宫格，shots 必须为 6，实际为 ' + expectedTotalPanels);
}

if (actualTotalPanels !== expectedTotalPanels) {
  throw new Error(
    '分镜提示词数量校验失败：前置 shots=' +
      expectedTotalPanels +
      '，但 storyboard_overview.total_panels=' +
      actualTotalPanels +
      '。当前工作流只允许 6 条 shot 对应 6 宫格，请重新生成分镜提示词。',
  );
}

return [
  {
    json: {
      ...(scriptRow || {}),
      ...(item.json || {}),
      project_id: item.json?.project_id || scriptRow.project_id || '',
      storyboard_overview: parsed.storyboard_overview || {},
      nanobanana_storyboard_prompt: parsed.nanobanana_storyboard_prompt || '',
      expected_total_panels: expectedTotalPanels,
      raw_storyboard_json: parsed
    }
  }
];

const data = {
  ...( $('Code in JavaScript2').first()?.json || {} ),
  ...( $('本地图片转Gemini输入').first()?.json || {} ),
  ...$json,
};

const projectId = data.project_id || data.storyboard_overview?.project_id || '';
const promptCore = data.nanobanana_storyboard_prompt || '';
const expectedTotalPanels = Number(data.expected_total_panels || data.storyboard_overview?.total_panels || 0);

function tpl(str, vars) {
  let out = str;
  for (const [k, v] of Object.entries(vars)) {
    out = out.split('{{' + k + '}}').join(v == null ? '' : String(v));
  }
  return out;
}

const promptsLib = $('Prompt Library').first().json;
const wrapperTpl = promptsLib.nanobanana_image?.english_storyboard_wrapper || 'Storyboard instructions:\n{{nanobanana_storyboard_prompt}}\n';
const reviewRound = Number(data.review_round || 1);
const reviewFeedback = String(data.review_feedback || '').trim();
const badShotIds = Array.isArray(data.bad_shot_ids_list)
  ? data.bad_shot_ids_list.map((x) => String(x).trim()).filter(Boolean)
  : String(data.bad_shot_ids || '').split(/[\n,，\s]+/).map((x) => x.trim()).filter(Boolean);

const reviewCorrectionBlock = reviewFeedback || badShotIds.length
  ? '\n\nHuman reviewer correction request (round ' + reviewRound + '):\n' +
    (badShotIds.length ? '- Regenerate and improve these panels first: ' + badShotIds.join(', ') + '\n' : '') +
    (reviewFeedback ? '- Reviewer feedback: ' + reviewFeedback + '\n' : '') +
    '- Keep all other approved panels as stable and consistent as possible.\n' +
    '- Maintain the same woman, styling, product identity, room, and overall continuity.\n'
  : '';

const finalPrompt = tpl(wrapperTpl, { nanobanana_storyboard_prompt: promptCore }).trim() + reviewCorrectionBlock +
  (expectedTotalPanels
    ? '\n\nAbsolute execution rule:\n- The final storyboard must contain exactly ' + expectedTotalPanels + ' panels.\n- Do not add extra panels.\n- Do not remove panels.\n- Panel count must exactly equal the provided shot count.\n'
    : '');

const imageCount = Number(data.product_image_count ?? data.image_count ?? 0);
const image1 = data.image_1_base64 || '';
const image2 = data.image_2_base64 || '';
const imgConf = promptsLib.nanobanana_image?.gemini_image_config || { aspectRatio: '4:5', imageSize: '2K' };
const parts = [{ text: finalPrompt }];
if (imageCount >= 1 && image1) parts.push({ inlineData: { mimeType: data.image_1_mime || 'image/jpeg', data: image1 } });
if (imageCount >= 2 && image2) parts.push({ inlineData: { mimeType: data.image_2_mime || 'image/jpeg', data: image2 } });

const geminiRequestBody = {
  contents: [{ role: 'user', parts }],
  generationConfig: {
    responseModalities: ['IMAGE'],
    thinkingConfig: { thinkingLevel: 'HIGH' },
    imageConfig: { aspectRatio: imgConf.aspectRatio, imageSize: imgConf.imageSize },
