function findImageData(value, seen = new Set()) {
  if (value == null) return null;
  if (typeof value !== 'object') return null;
  if (seen.has(value)) return null;
  seen.add(value);

  if (value.inlineData?.data) {
    return {
      mimeType: value.inlineData.mimeType || 'image/jpeg',
      data: value.inlineData.data,
      source: 'inlineData',
    };
  }

  if (value.inline_data?.data) {
    return {
      mimeType: value.inline_data.mime_type || value.inline_data.mimeType || 'image/jpeg',
      data: value.inline_data.data,
      source: 'inline_data',
    };
  }

  if (looksLikeBase64(value.data) && (value.mimeType || value.mime_type)) {
    return {
      mimeType: value.mimeType || value.mime_type || 'image/jpeg',
      data: value.data,
      source: 'direct-data',
    };
  }

  if (Array.isArray(value)) {
    for (const entry of value) {
      const found = findImageData(entry, seen);
      if (found) return found;
    }
    return null;
  }

  const preferredKeys = ['body', 'data', 'candidates', 'content', 'parts', 'response'];
  for (const key of preferredKeys) {
    if (key in value) {
      const found = findImageData(value[key], seen);
      if (found) return found;
    }
  }

  for (const entry of Object.values(value)) {
    const found = findImageData(entry, seen);
    if (found) return found;
  }
  return null;
}

