    '<p>' +
    meta +
    '</p>' +
    (previewUrl
      ? '<p><img src="' + previewUrl + '" alt="' + title + '" width="220" /></p>'
      : '<p>预览图暂不可用，请根据镜头编号核对。</p>') +
    '<p><strong>对应视频提示词</strong></p>' +
    '<pre>' +
    prompt +
    '</pre>' +
    '<hr />' +
    '</div>';
}

const reviewHtml =
  '<div>' +
  '<p><strong>请检查每张切割后的分镜图与对应提示词是否匹配。</strong></p>' +
  '<p>如果全部合适，选择“确认通过”。如果有问题，选择“需要重做”，并填写需要重做的镜头编号，例如 <code>2, 5</code> 或 <code>shot_2, shot_5</code>，再写清楚修改意见。</p>' +
  '<p>当前轮次：第 ' +
  reviewRound +
  ' 轮，项目：' +
  esc(projectId) +
  (productName ? '，产品：' + esc(productName) : '') +
  '。</p>' +
  cards +
  '</div>';

return [
  {
    json: {
      project_id: projectId,
      product_name: productName,
      panel_count: panels.length,
      review_round: reviewRound,
      review_context_path: contextPath,
      review_form_html: reviewHtml,
    },
  },
];
